reference_solution:
def getModifiedArray(length, updates):
    diff = [0] * (length + 1)
    for s, e, inc in updates:
        diff[s] += inc
        diff[e + 1] -= inc
    out, run = [], 0
    for i in range(length):
        run += diff[i]
        out.append(run)
    return out

